<script setup>
import { ref } from 'vue'
import { SHOPPING_STOREFRONT_EVENTS, SHOPPING_STOREFRONT_PROPS, localizeShoppingCopy } from './shopping-storefront-contract'

const props = defineProps(SHOPPING_STOREFRONT_PROPS)
const emit = defineEmits(SHOPPING_STOREFRONT_EVENTS)
const localize = (zh, en) => localizeShoppingCopy(props.languageBase, zh, en)
const searchChanged = (event) => emit('update:searchQuery', event.target.value)
const cuMode = ref('pickup')
const pickupStage = ref('inventory')
const activePromo = ref('hot-counter')
const services = Object.freeze([
  { key: 'inventory', icon: 'fas fa-magnifying-glass-location', zh: '门店库存', en: 'Find stock', note: ['先选店再找货', 'Store-first search'] },
  { key: 'pickup', icon: 'fas fa-bag-shopping', zh: '预约取货', en: 'Pickup', note: ['按时间备货', 'Ready by slot'] },
  { key: 'delivery', icon: 'fas fa-motorcycle', zh: '即时配送', en: 'Delivery', note: ['附近门店出发', 'From nearby CU'] },
  { key: 'reservation', icon: 'fas fa-calendar-check', zh: '限定预约', en: 'Reserve', note: ['新品与联名', 'Drops & collabs'] },
])
const promos = Object.freeze([
  { key: 'hot-counter', icon: 'fas fa-fire-flame-curved', zh: '热柜刚出炉', en: 'HOT COUNTER', note: ['现在适合夜宵', 'Late-night ready'] },
  { key: 'cold-shelf', icon: 'fas fa-snowflake', zh: '冷藏搭配', en: 'CHILLED PAIR', note: ['饭团、饮料、甜点', 'Meals, drinks, sweets'] },
  { key: 'one-plus-one', icon: 'fas fa-plus', zh: '本周 1+1', en: '1+1 THIS WEEK', note: ['会员权益专区', 'Member benefits'] },
])
const chooseService = (key) => {
  pickupStage.value = key
  if (key === 'pickup' || key === 'delivery') cuMode.value = key
}
</script>

<template>
  <header class="shopping-storefront-header shopping-cu-app cu-app" :data-storefront="activeService?.storefrontTemplate || 'neighborhood_convenience'" :data-cu-mode="cuMode" :data-pickup-stage="pickupStage">
    <div class="cu-appbar"><button data-testid="shopping-go-home" :aria-label="localize('返回主屏幕','Back to Home')" @click="emit('go-home')"><i class="fas fa-arrow-left"></i></button><div class="cu-brand"><b>CU</b><span><h1>{{ activeLabel || 'Pocket CU' }}</h1><small>NICE TO CU</small></span></div><button :aria-label="localize('我的 CU','My CU')" @click="emit('open-orders')"><i class="fas fa-user"></i><em v-if="orderCount">{{ orderCount }}</em></button></div>
